def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        for base in cls.__bases__:
            if base not in seen:
                seen.add(base)
                result.append(base)
        result.append(cls)
    return result
