def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    if not isinstance(commands, list):
        commands = [commands]

    if args:
        commands.extend(args)

    try:
        if hide_stderr:
            output = subprocess.check_output(commands, cwd=cwd, env=env, stderr=subprocess.STDOUT)
        else:
            output = subprocess.check_output(commands, cwd=cwd, env=env)

        if verbose:
            print(output.decode())

        return output

    except subprocess.CalledProcessError as e:
        if verbose:
            print(e.output.decode())
        raise Exception(f"Command failed: {' '.join(commands)}")
